"""Evaluates notification rules: skipped executions, SLA breaches, and errors."""
import pandas as pd

RULE_TYPES = ("skipped", "sla_breach", "error")


def evaluate_rules(configs, runs, rules, start, end):
    """Return notifications generated by the configured rules."""
    cfg = configs.set_index("integration_id")
    notifications = []

    for rule in rules.itertuples(index=False):
        iid = rule.integration_id
        integration_runs = runs[runs["integration_id"] == iid]

        if rule.rule_type == "error":
            for execution in integration_runs[
                integration_runs["status"] == "error"
            ].itertuples(index=False):
                notifications.append((
                    iid,
                    "error",
                    execution.scheduled_at,
                    "Execution failed",
                ))

        elif rule.rule_type == "sla_breach":
            sla = cfg.loc[iid, "sla_min"]
            if pd.isna(sla):
                continue
            late = integration_runs[
                (integration_runs["status"] == "success")
                & (integration_runs["duration_min"] > sla)
            ]
            for execution in late.itertuples(index=False):
                notifications.append((
                    iid,
                    "sla_breach",
                    execution.scheduled_at,
                    f"Duration {execution.duration_min} min exceeded SLA {sla} min",
                ))

        elif rule.rule_type == "skipped":
            frequency = f"{int(cfg.loc[iid, 'interval_min'])}min"
            expected = pd.date_range(start, end, freq=frequency, inclusive="left")
            missing = expected.difference(
                pd.DatetimeIndex(integration_runs["scheduled_at"])
            )
            for timestamp in missing:
                notifications.append((
                    iid,
                    "skipped",
                    timestamp,
                    "Expected execution did not run",
                ))

    return pd.DataFrame(
        notifications,
        columns=["integration_id", "rule_type", "occurred_at", "message"],
    )
